private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_vibecrafted_shell_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_get_recent_logs() != 12164) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_get_routes() != 40408) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_get_server_status() != 17348) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_init_runtime() != 22518) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_load_mission_control_snapshot() != 40441) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_load_mission_control_snapshot_at() != 11312) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_load_run_detail() != 9516) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_load_run_detail_at() != 24709) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_restart_service() != 60065) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_subscribe_events() != 65076) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_func_verify_client() != 11223) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_method_eventcallback_on_event() != 6295) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vibecrafted_shell_ffi_checksum_method_eventcallback_on_error() != 16499) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitEventCallback()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureVibecraftedShellFfiInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

